/* 对射式红外传感器计次：PB14 下降沿触发外部中断（EXTI15_10 通道） */
void CountSensor_Init(void) {
    RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOB, ENABLE);   // 开 GPIOB 时钟
    RCC_APB2PeriphClockCmd(RCC_APB2Periph_AFIO, ENABLE);    // 开 AFIO 时钟（EXTI/NVIC 不用开）

    GPIO_InitTypeDef GPIO_InitStructure;
    GPIO_InitStructure.GPIO_Mode = GPIO_Mode_IPU;           // 上拉输入
    GPIO_InitStructure.GPIO_Pin = GPIO_Pin_14;
    GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;
    GPIO_Init(GPIOB, &GPIO_InitStructure);

    GPIO_EXTILineConfig(GPIO_PortSourceGPIOB, GPIO_PinSource14); // AFIO 选 PB14 接 EXTI14

    EXTI_InitTypeDef EXTI_InitStructure;
    EXTI_InitStructure.EXTI_Line = EXTI_Line14;              // 第14线
    EXTI_InitStructure.EXTI_LineCmd = ENABLE;
    EXTI_InitStructure.EXTI_Mode = EXTI_Mode_Interrupt;     // 中断响应
    EXTI_InitStructure.EXTI_Trigger = EXTI_Trigger_Falling; // 下降沿触发
    EXTI_Init(&EXTI_InitStructure);

    NVIC_PriorityGroupConfig(NVIC_PriorityGroup_2);         // 分组：2抢占2响应
    NVIC_InitTypeDef NVIC_InitStructure;
    NVIC_InitStructure.NVIC_IRQChannel = EXTI15_10_IRQn;    // 15~10 合并通道
    NVIC_InitStructure.NVIC_IRQChannelCmd = ENABLE;
    NVIC_InitStructure.NVIC_IRQChannelPreemptionPriority = 1;
    NVIC_InitStructure.NVIC_IRQChannelSubPriority = 1;
    NVIC_Init(&NVIC_InitStructure);
}

// 中断服务函数（名字从启动文件复制，不可写错）
void EXTI15_10_IRQHandler(void) {
    if (EXTI_GetITStatus(EXTI_Line14) == SET) {  // 确认是 EXTI14 触发
        CountSensor_Count++;                     // 计次+1
        EXTI_ClearITPendingBit(EXTI_Line14);     // 必须清除标志位，否则反复进中断
    }
}

void Timer_Init(void) {
    RCC_APB1PeriphClockCmd(RCC_APB1Periph_TIM2, ENABLE);  // TIM2在APB1
    TIM_InternalClockConfig(TIM2);                       // 选内部时钟(默认即此)
    TIM_TimeBaseInitTypeDef tb;
    tb.TIM_ClockDivision = TIM_CKD_DIV1;
    tb.TIM_CounterMode = TIM_CounterMode_Up;             // 向上计数
    tb.TIM_Period = 10000 - 1;                           // ARR 自动重装
    tb.TIM_Prescaler = 7200 - 1;                         // PSC: 72M/7200/10000 = 1Hz
    tb.TIM_RepetitionCounter = 0;
    TIM_TimeBaseInit(TIM2, &tb);
    TIM_ClearFlag(TIM2, TIM_FLAG_Update);               // 防一上电就进中断
    TIM_ITConfig(TIM2, TIM_IT_Update, ENABLE);          // 使能更新中断
    NVIC_PriorityGroupConfig(NVIC_PriorityGroup_2);
    NVIC_InitTypeDef ni;
    ni.NVIC_IRQChannel = TIM2_IRQn;
    ni.NVIC_IRQChannelPreemptionPriority = 2;
    ni.NVIC_IRQChannelSubPriority = 1;
    ni.NVIC_IRQChannelCmd = ENABLE;
    NVIC_Init(&ni);
    TIM_Cmd(TIM2, ENABLE);                              // 启动计数器
}
void TIM2_IRQHandler(void) {
    if (TIM_GetITStatus(TIM2, TIM_IT_Update) == SET) {
        // 用户代码: number++;
        TIM_ClearITPendingBit(TIM2, TIM_IT_Update);
    }
}

