// 固定包长 HEX 包：FF + 4字节数据 + FE，用状态机在接收中断里收
#define SOP 0xFF
#define EOP 0xFE
uint8_t RxPacket[4];
uint8_t RxFlag = 0;
void USART1_IRQHandler(void) {
    static uint8_t State = 0;
    static uint8_t p = 0;
    if (USART_GetITStatus(USART1, USART_IT_RXNE) == SET) {
        uint8_t RxData = USART_ReceiveData(USART1);
        if (State == 0) {            // 等包头
            if (RxData == SOP) State = 1;
        } else if (State == 1) {     // 收数据
            RxPacket[p++] = RxData;
            if (p >= 4) { p = 0; State = 2; }
        } else if (State == 2) {     // 等包尾
            if (RxData == EOP) { State = 0; RxFlag = 1; }
        }
        USART_ClearITPendingBit(USART1, USART_IT_RXNE);
    }
}

// 文本包接收（@ 开头，\r\n 结尾），收到后置标志并补字符串结束符
void USART1_IRQHandler(void) {
    static uint8_t State = 0;
    if (USART_GetITStatus(USART1, USART_IT_RXNE) == SET) {
        uint8_t RxData = USART_ReceiveData(USART1);
        if (RxData == '@' && Serial_RxFlag == 0) State = 1;  // 仅在空闲时响应新包
        else if (State == 1) {
            if (RxData == '\r') State = 2;
            else Serial_RxPacket[Serial_RxLen++] = RxData;
        } else if (State == 2) {
            if (RxData == '\n') {
                Serial_RxPacket[Serial_RxLen] = '\0';  // 补结束符
                Serial_RxFlag = 1; State = 0; Serial_RxLen = 0;
            }
        }
        USART_ClearITPendingBit(USART1, USART_IT_RXNE);
    }
}
// 主循环：匹配指令
if (Serial_RxFlag == 1) {
    OLED_ShowString(4,1, "                ");
