    Serial_RxFlag = 0;  // 处理完才清标志，防错位
}

// 软件 I2C 六个基本单元（节选）
void MyI2C_Start(void) {
    MyI2C_W_SDA(1); MyI2C_W_SCL(1);   // 先确保都释放
    MyI2C_W_SDA(0); MyI2C_W_SCL(0);   // 下降沿=起始
}
void MyI2C_Stop(void) {
    MyI2C_W_SDA(0); MyI2C_W_SCL(1); MyI2C_W_SDA(1); // 上升沿=停止
}
void MyI2C_SendByte(uint8_t Byte) {
    for (uint8_t i=0; i<8; i++) {
        MyI2C_W_SDA(Byte & (0x80 >> i)); // 高位先行
        MyI2C_W_SCL(1); MyI2C_W_SCL(0);  // 给时钟脉冲，从机读取
    }
    MyI2C_W_SDA(1); // 释放，准备收应答
}
// 指定地址读一字节
uint8_t MPU6050_ReadReg(uint8_t RegAddr) {
    uint8_t Data;
    MyI2C_Start();
    MyI2C_SendByte(0xD0); MyI2C_ReceiveAck();   // 写模式寻址
    MyI2C_SendByte(RegAddr); MyI2C_ReceiveAck();
    MyI2C_Start();                                // 重复起始
    MyI2C_SendByte(0xD1); MyI2C_ReceiveAck();   // 读模式寻址
    Data = MyI2C_ReceiveByte(); MyI2C_SendAck(1);// 收数据+NACK
    MyI2C_Stop();
    return Data;
}

// 硬件 I2C2 初始化（PB10=SCL，PB11=SDA，100k）
void MPU6050_I2C_Init(void) {
    RCC_APB1PeriphClockCmd(RCC_APB1Periph_I2C2, ENABLE);
    RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOB, ENABLE);
    GPIO_InitTypeDef G;
    G.GPIO_Pin = GPIO_Pin_10 | GPIO_Pin_11;
    G.GPIO_Mode = GPIO_Mode_AF_OD;          // 复用开漏
    G.GPIO_Speed = GPIO_Speed_50MHz;
    GPIO_Init(GPIOB, &G);
    I2C_InitTypeDef I;
    I.I2C_Mode = I2C_Mode_I2C;
    I.I2C_ClockSpeed = 100000;             // 标准模式
    I.I2C_DutyCycle = I2C_DutyCycle_2;
    I.I2C_Ack = I2C_Ack_Enable;
    I.I2C_OwnAddress1 = 0x00;
    I.I2C_AcknowledgedStandard = I2C_AcknowledgedStandard_7bit;
    I2C_Init(I2C2, &I);
    I2C_Cmd(I2C2, ENABLE);
}
// 指定地址读一字节（硬件 I2C）
uint8_t MPU6050_ReadReg(uint8_t RegAddr) {
    uint8_t Data;
    I2C_GenerateSTART(I2C2, ENABLE);
    while (I2C_CheckEvent(I2C2, I2C_EVENT_MASTER_MODE_SELECT) != SUCCESS);   // EV5
    I2C_Send7bitAddress(I2C2, 0xD0, I2C_Direction_Transmitter);
    while (I2C_CheckEvent(I2C2, I2C_EVENT_MASTER_TRANSMITTER_MODE_SELECTED) != SUCCESS); // EV6
    I2C_SendData(I2C2, RegAddr);
    while (I2C_CheckEvent(I2C2, I2C_EVENT_MASTER_BYTE_TRANSMITTED) != SUCCESS); // EV8
    I2C_GenerateSTART(I2C2, ENABLE);                                         // 重复起始
    while (I2C_CheckEvent(I2C2, I2C_EVENT_MASTER_MODE_SELECT) != SUCCESS);
    I2C_Send7bitAddress(I2C2, 0xD0, I2C_Direction_Receiver);
    while (I2C_CheckEvent(I2C2, I2C_EVENT_MASTER_RECEIVER_MODE_SELECTED) != SUCCESS);
    while (I2C_CheckEvent(I2C2, I2C_EVENT_MASTER_BYTE_RECEIVED) != SUCCESS);
    Data = I2C_ReceiveData(I2C2);
    I2C_GenerateSTOP(I2C2, ENABLE);
    return Data;
}

/* MySPI 底层：起始/终止/交换一个字节(SPI模式0) */
void MySPI_Start(void)   { MySPI_W_SS(0); }          // SS拉低
void MySPI_Stop(void)    { MySPI_W_SS(1); }          // SS拉高
uint8_t MySPI_SwapByte(uint8_t ByteSend) {
    uint8_t ByteReceive = 0x00;
    for (uint8_t i = 0; i < 8; i++) {
        MySPI_W_MOSI(ByteSend & (0x80 >> i));        // 上升沿前: 最高位放到MOSI
        MySPI_W_SCK(1);                                // 上升沿: 主机读MISO
        if (MySPI_R_MISO() == 1) { ByteReceive |= (0x80 >> i); }
        MySPI_W_SCK(0);                                // 下降沿: 移除下一位
    }
    return ByteReceive;
}
/* W25Q64 驱动: 读ID(厂商EF/设备4017) */
void W25Q64_ReadID(uint8_t *MID, uint16_t *DID) {
    MySPI_Start();
    MySPI_SwapByte(0x9F);                             // 读ID指令
    *MID = MySPI_SwapByte(0xFF);                      // 厂商ID
    *DID = MySPI_SwapByte(0xFF);                      // 设备ID高8位
    *DID = (*DID << 8) | MySPI_SwapByte(0xFF);        // 设备ID低8位
    MySPI_Stop();
}

/* 硬件SPI初始化(模式0, 分频/128) */
void MySPI_Init(void) {
    RCC_APB2PeriphClockCmd(RCC_APB2Periph_SPI1 | RCC_APB2Periph_GPIOA, ENABLE);
    GPIO_InitTypeDef gi;
    gi.GPIO_Mode = GPIO_Mode_Out_PP; gi.GPIO_Pin = GPIO_Pin_4; gi.GPIO_Speed = GPIO_Speed_50MHz; GPIO_Init(GPIOA, &gi); // SS软件
    gi.GPIO_Mode = GPIO_Mode_AF_PP;  gi.GPIO_Pin = GPIO_Pin_5 | GPIO_Pin_7; GPIO_Init(GPIOA, &gi); // SCK/MOSI复用推挽
    gi.GPIO_Mode = GPIO_Mode_IPU;    gi.GPIO_Pin = GPIO_Pin_6; GPIO_Init(GPIOA, &gi); // MISO上拉输入
    SPI_InitTypeDef si;
    si.SPI_Direction = SPI_Direction_2Lines_FullDuplex;
    si.SPI_DataSize = SPI_DataSize_8b;
    si.SPI_FirstBit = SPI_FirstBit_MSB;
    si.SPI_BaudRatePrescaler = SPI_BaudRatePrescaler_128;
    si.SPI_CPOL = SPI_CPOL_Low; si.SPI_CPHA = SPI_CPHA_1Edge; // 模式0
    si.SPI_NSS = SPI_NSS_Soft; si.SPI_CRCPolynomial = 7;
    SPI_Init(SPI1, &si);
    SPI_Cmd(SPI1, ENABLE);
    MySPI_W_SS(1);
}
/* 交换一个字节 */
uint8_t MySPI_SwapByte(uint8_t ByteSend) {
    while (SPI_I2S_GetFlagStatus(SPI1, SPI_I2S_FLAG_TXE) == RESET);
    SPI_I2S_SendData(SPI1, ByteSend);
    while (SPI_I2S_GetFlagStatus(SPI1, SPI_I2S_FLAG_RXNE) == RESET);
    return SPI_I2S_ReceiveData(SPI1);
}

