    PWR_BackupAccessCmd(ENABLE);                 // 使能对BKP/RTC访问
    RCC_LSEConfig(RCC_LSE_ON);                   // 开启LSE
    while (RCC_GetFlagStatus(RCC_FLAG_LSERDY) == RESET); // 等LSE就绪
    RCC_RTCCLKConfig(RCC_RTCCLKSource_LSE);      // 选RTCCLK=LSE
    RCC_RTCCLKCmd(ENABLE);
    RTC_WaitForSynchro();                        // 等待同步
    RTC_WaitForLastTask();                       // 等待上次操作完成
    RTC_SetPrescaler(32767);                     // 32768分频 -> 1Hz
    RTC_WaitForLastTask();
    RTC_SetCounter(1672588795);                  // 设初始时间(2023-01-01)
