#include "stm32f10x.h"

/* 读一个字(32位)。注意地址参数永远是 uint32_t —— 地址是32位的“门牌号” */
uint32_t MyFlash_ReadWord(uint32_t Address)
{
    return *((__IO uint32_t *)(Address));   // 地址强转成32位指针再取内容
}

uint16_t MyFlash_ReadHalfWord(uint32_t Address)
{
    return *((__IO uint16_t *)(Address));   // 强转16位指针 -> 读半字
}

uint8_t MyFlash_ReadByte(uint32_t Address)
{
    return *((__IO uint8_t *)(Address));    // 强转8位指针 -> 读字节
}

/* 全擦除：整片主闪存恢复成0xFF，程序自己也会被擦掉，慎用！ */
void MyFlash_EraseAllPages(void)
{
    FLASH_Unlock();          // 第一步：解锁，不解锁擦不动
    FLASH_EraseAllPages();   // 第二步：调库，内部已含置位/等待忙/清标志
    FLASH_Lock();            // 第三步：加锁，防止后续误操作
}

/* 页擦除：只擦指定的一页（F103C8T6 一页 = 1KB = 1024字节） */
void MyFlash_ErasePage(uint32_t PageAddress)
{
    FLASH_Unlock();
    FLASH_ErasePage(PageAddress);   // 参数给这一页的起始地址，如0x0800FC00
    FLASH_Lock();
}

/* 编程：在指定地址写入一个字(32位) */
void MyFlash_ProgramWord(uint32_t Address, uint32_t Data)
{
    FLASH_Unlock();
    FLASH_ProgramWord(Address, Data);
    FLASH_Lock();
}

/* 编程：写入一个半字(16位)。闪存最小写入单位是半字，故没有写字节的函数 */
void MyFlash_ProgramHalfWord(uint32_t Address, uint16_t Data)
{
    FLASH_Unlock();
    FLASH_ProgramHalfWord(Address, Data);
    FLASH_Lock();
}

/* ===== Store.c 上层模块：SRAM数组托管闪存最后一页，实现掉电不丢失 ===== */
#include "MyFlash.h"
#define STORE_START_ADDRESS  0x0800FC00   // 64KB闪存最后一页的起始地址
#define STORE_COUNT          512          // 512个半字 = 1024字节 = 正好一页

uint16_t Store_Data[STORE_COUNT];         // SRAM缓存数组：当“草稿纸”随便改

void Store_Init(void)
{
    /* 用第0个数据当标志位：不等于0xA5A5说明是第一次使用这块闪存 */
    if (MyFlash_ReadHalfWord(STORE_START_ADDRESS) != 0xA5A5)
    {
        MyFlash_ErasePage(STORE_START_ADDRESS);   // 先把这一页擦干净
        Store_Data[0] = 0xA5A5;                   // 写入标志位
        for (uint16_t i = 1; i < STORE_COUNT; i ++)
        {
            Store_Data[i] = 0x0000;               // 其余参数清零
        }
        Store_Save();                             // 备份到闪存
    }
    else   /* 不是第一次：把闪存里的存档搬回SRAM数组 */
    {
        for (uint16_t i = 0; i < STORE_COUNT; i ++)
        {
            Store_Data[i] = MyFlash_ReadHalfWord(STORE_START_ADDRESS + i * 2);
        }
    }
}

/* 保存：写之前必须先擦除整页，再把数组逐个半字写回去 */
void Store_Save(void)
{
    MyFlash_ErasePage(STORE_START_ADDRESS);
    for (uint16_t i = 0; i < STORE_COUNT; i ++)
    {
        MyFlash_ProgramHalfWord(STORE_START_ADDRESS + i * 2, Store_Data[i]);
    }
}

